args:
$source = '${file}'
$root = '${workspaceFolder}'
if ((Get-Content -Raw -LiteralPath $source) -notmatch '\bmain\s*\(') { Write-Error 'The active C++ file does not define main(); select an entry point.'; exit 2 }
$sources = [System.Collections.Generic.List[string]]::new()
$sourcePaths = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$pending = [System.Collections.Generic.Queue[string]]::new()
$visited = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$sources.Add($source)
$sourcePaths.Add($source) | Out-Null
$pending.Enqueue($source)
while ($pending.Count -gt 0) {
    $current = $pending.Dequeue()
    if (-not $visited.Add($current)) { continue }
    $content = Get-Content -Raw -LiteralPath $current
    foreach ($include in [regex]::Matches($content, '#include\s+"([^"]+)"')) {
        $header = Join-Path (Split-Path -Parent $current) $include.Groups[1].Value
        if (-not (Test-Path -LiteralPath $header)) { continue }
        $pending.Enqueue($header)
        $implementationName = [IO.Path]::GetFileNameWithoutExtension($header) + '.cpp'
        $implementation = Get-ChildItem -LiteralPath $root -Filter '*.cpp' -File | Where-Object { $_.Name -ieq $implementationName } | Select-Object -First 1
        if ($implementation -and $sourcePaths.Add($implementation.FullName)) {
            $sources.Add($implementation.FullName)
            $pending.Enqueue($implementation.FullName)
        }
    }
}
$output = Join-Path (Split-Path -Parent $source) (([IO.Path]::GetFileNameWithoutExtension($source)) + '.exe')
& 'C:\msys64\ucrt64\bin\g++.exe' -fdiagnostics-color=always -g $sources.ToArray() -o $output
exit $LASTEXITCODE
